import { Plugin } from '../index.js';
import { ParserOptions } from '@apidevtools/json-schema-ref-parser';
import 'json-schema';

interface RefsPluginOptions extends ParserOptions {
    cwd?: string;
}
/**
 * A plugin to resolve $refs in input schema.
 *
 * Uses and requires `@apidevtools/json-schema-ref-parser` to be installed in runtime.
 *
 * @param options - [$RefParser](https://github.com/APIDevTools/json-schema-ref-parser) Options, used when resolving `$ref`s
 */
declare function refsPlugin(options?: RefsPluginOptions): Plugin;

export { type RefsPluginOptions, refsPlugin };
